/**
 * The column holding each table's café: `id` for cafes itself, `cafe_id` for café tables, null for the two global
 * tables (customers, reached only through cards, and customer recovery tokens), which have their own tests.
 */
export const TENANT_KEY: Readonly<Record<TableName, "id" | "cafe_id" | null>> = {
  cafes: "id",
  loyalty_programs: "cafe_id",
  order_types: "cafe_id",
  audit_log: "cafe_id",
  owners: "cafe_id",
  owner_invites: "cafe_id",
  owner_sessions: "cafe_id",
  password_reset_tokens: "cafe_id",
  staff: "cafe_id",
  devices: "cafe_id",
  device_keys: "cafe_id",
  device_tokens: "cafe_id",
  pairing_codes: "cafe_id",
  cards: "cafe_id",
  customers: null,
  customer_recovery_tokens: null,
  sync_events: "cafe_id",
  visits: "cafe_id",
  visit_items: "cafe_id",
  redemptions: "cafe_id",
  apple_passes: "cafe_id",
  apple_pass_registrations: "cafe_id",
  google_passes: "cafe_id",
};

type ListedColumns = { [T in TableName]: (typeof TABLE_COLUMNS)[T][number] };
type CompletenessByTable = { [T in TableName]: [Exclude<keyof Database[T], ListedColumns[T]>] extends [never] ? true : false };
type AssertAllTrue<X extends Record<TableName, true>> = X;
/** Compile-time check that TABLE_COLUMNS lists every column of the Database interface; fails to compile otherwise. */
export type TableColumnsAreComplete = AssertAllTrue<CompletenessByTable>;
